const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const projects=[{name:'Olive Grove',city:'Santa Ana',homes:8,cost:4160000,funding:3020000,status:'Building the stack',color:'green',tone:'#b0bca1'},{name:'Magnolia Court',city:'Fullerton',homes:12,cost:6840000,funding:4580000,status:'Funding in progress',color:'amber',tone:'#c6bca8'},{name:'Cypress Commons',city:'Anaheim',homes:8,cost:3820000,funding:3040000,status:'Almost there',color:'green',tone:'#a9b7ad'}];
function house(t){return `<svg viewBox="0 0 100 120" xmlns="http://www.w3.org/2000/svg"><rect width="100" height="120" fill="${t}"/><circle cx="83" cy="17" r="19" fill="#e4e9d6"/><path d="M-5 46L51 16 108 47" fill="#617160"/><path d="M9 43L51 21 92 43V105H9Z" fill="#ece9da"/><path d="M50 22V105H92V44Z" fill="#dedccf"/><path d="M9 46H92" stroke="#b2b2a0" stroke-width="3"/><rect x="20" y="53" width="17" height="23" fill="#6d8984"/><rect x="61" y="53" width="18" height="23" fill="#6d8984"/><path d="M28 53V76M20 65H37M70 53V76M61 65H79" stroke="#dedfd2"/><rect x="43" y="78" width="17" height="28" fill="#9b967e"/><path d="M0 107H100V120H0Z" fill="#8d9e7c"/><path d="M39 120L44 105H60L68 120" fill="#d6d4bf"/><circle cx="7" cy="95" r="12" fill="#627959"/><circle cx="92" cy="91" r="15" fill="#758664"/></svg>`}
function renderProjects(){ $('#projectList').innerHTML=projects.slice(0,3).map((p,i)=>`<article class="project" tabindex="0" role="button" aria-label="Open ${p.name}" data-project="${i}"><div class="house-thumb">${house(p.tone)}</div><div><div class="project-top"><h3>${p.name}</h3><span class="badge ${p.color}">${p.status}</span></div><p class="location">${p.city}, CA &nbsp; · &nbsp; ${p.homes} homes &nbsp; · &nbsp; Affordable ownership</p><div class="project-values"><div><small>Development cost</small><b>${money(p.cost)}</b></div><div><small>Committed funding</small><b>${money(p.funding)}</b></div><div><small>Remaining gap ↗</small><b>${money(p.cost-p.funding)}</b></div></div><div class="progress-track"><span style="width:${p.funding/p.cost*100}%"></span></div><div class="project-foot"><span>${Math.round(p.funding/p.cost*100)}% funded</span><span>View project →</span></div></div></article>`).join('');$$('[data-project]').forEach(e=>{e.onclick=()=>openProject(+e.dataset.project);e.onkeydown=k=>{if(k.key==='Enter')e.click()}})}
function view(id){$$('.view').forEach(e=>e.classList.toggle('hidden',e.id!==id));$$('nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===id));$('#breadcrumb').textContent={overview:'Overview',discover:'Discover Homes',projects:'Projects',funding:'Funding opportunities',listings:'Listings',buyers:'Buyer profiles',sources:'Sources & assumptions'}[id];window.scrollTo(0,0);window.dispatchEvent(new CustomEvent('fundit:view',{detail:id}))}
$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$$('[data-goto]').forEach(b=>b.onclick=()=>view(b.dataset.goto));
function openProject(i){let p=projects[i];$('#calcProject').textContent=p.name;$('#cost').value=Math.round(p.cost/p.homes);$('#subsidy').value=100000;view('projects');calculate()}
const get=id=>Math.max(0,+$('#'+id).value||0);let scenario;
function calculation(rate){let budget=get('income')/12*Math.min(100,get('ratio'))/100, pi=Math.max(0,budget-get('expenses')),r=rate/1200,loan=r?pi*(1-Math.pow(1+r,-360))/r:pi*360;let power=loan+get('down');return {budget,pi,loan,power,gap:Math.max(0,get('cost')-power-get('subsidy'))}}
function calculate(){let rate=get('rate');scenario=calculation(rate);$('#rateValue').textContent=rate.toFixed(3).replace(/0$/,'')+'%';$('#gapOutput').textContent=money(scenario.gap);$('#calcRows').innerHTML=[['Monthly housing budget',money(scenario.budget)],['Monthly principal & interest',money(scenario.pi)],['Affordable first mortgage',money(scenario.loan)],['Buyer purchasing power',money(scenario.power)],['Committed subsidy',money(get('subsidy'))]].map(([a,b])=>`<div class="calc-row"><span>${a}</span><b>${b}</b></div>`).join('');$('#sensitivity').innerHTML=[-.5,0,.5].map(d=>`<div class="calc-row"><span>${(rate+d).toFixed(2)}% ${d===0?'· Current scenario':''}</span><b>${money(calculation(rate+d).gap)} gap</b></div>`).join('')}
$$('#projects input').forEach(e=>e.oninput=calculate);$('#exploreRates').onclick=()=>{view('projects');calculate()};$('#export').onclick=()=>{let data={project:$('#calcProject').textContent,assumptions:Object.fromEntries(['cost','income','down','expenses','ratio','subsidy','rate'].map(k=>[k,get(k)])),results:scenario,notice:'Illustrative planning estimate; not an eligibility or lending decision.'};let url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='fund-it-scenario.json';a.click();URL.revokeObjectURL(url);toast('Scenario exported')};
const funds=[{name:'CalHome Program',type:'State',desc:'Funding to eligible local public agencies and nonprofits for homeownership assistance.',url:'https://www.hcd.ca.gov/grants-and-funding/programs-active/calhome',review:'Verify the local administrator, available allocation, income table, property rules, deferred loan terms and affordability restrictions. No benefit amount is assumed.'},{name:'HOME Investment Partnerships',type:'Federal',desc:'Locally administered federal funds that may support affordable homeownership.',url:'https://www.hud.gov/program_offices/comm_planning/home',review:'Contact the participating jurisdiction. Verify HOME-specific income and property limits, subsidy layering, recapture or resale requirements and funding availability.'},{name:'Employer housing benefits',type:'Employer',desc:'Ask about employer or institutional down-payment and homeownership support.',url:null,review:'No employer award has been identified. Ask the buyer whether a benefit exists, then verify employment tenure, property geography, repayment and stacking restrictions with the employer.'}];
function renderFunds(){let q=$('#fundSearch').value.toLowerCase(),t=$('#fundType').value;let list=funds.filter(f=>f.name.toLowerCase().includes(q)&&(t==='All categories'||f.type===t));$('#fundCards').innerHTML=list.length?list.map(f=>`<article class="panel fund-card"><span class="badge amber">Funds unconfirmed</span><h2>${f.name}</h2><span class="tiny-label">${f.type.toUpperCase()}</span><p>${f.desc}</p><p>${f.review}</p>${f.url?`<a href="${f.url}" target="_blank" rel="noreferrer">Review official program ↗</a>`:'<small class="muted">Buyer follow-up required</small>'}</article>`).join(''):'<p class="muted">No matching opportunities. Try another category or search.</p>'}
$('#fundSearch').oninput=renderFunds;$('#fundType').onchange=renderFunds;
const modal=$('#modal');function showModal(html){$('#modalBody').innerHTML=html;modal.showModal()}$('.close').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal)modal.close()};$$('[data-program]').forEach(e=>e.onclick=()=>{let f=funds.find(f=>f.name===e.dataset.program);showModal(`<span class="badge amber">Funds unconfirmed</span><h1 style="margin-top:20px">${f.name}</h1><p>${f.desc}</p><p>${f.review}</p><a href="${f.url}" target="_blank" rel="noreferrer">Official program information ↗</a>`)})
$('#newProject').onclick=()=>{showModal(`<h1>Start with a home.</h1><p>Create an illustrative project scenario. No data leaves this session.</p><form id="newForm"><div class="dialog-fields"><label>Project name<input required name="name" placeholder="e.g. Valencia Place" maxlength="70"></label><label>City<input required name="city" placeholder="e.g. Santa Ana" maxlength="70"></label><label>Number of homes<input required name="homes" type="number" min="1" max="10000" value="8"></label><label>Development cost per home<input required name="cost" type="number" min="1" value="520000"></label></div><button class="primary">Create scenario →</button></form>`);$('#newForm').onsubmit=e=>{e.preventDefault();let d=new FormData(e.target),p={name:d.get('name'),city:d.get('city'),homes:+d.get('homes'),cost:+d.get('cost')*+d.get('homes'),funding:0};projects.push(p);modal.close();openProject(projects.length-1);$('#subsidy').value=0;calculate();toast('New scenario created for this session')}};
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}$('#notifications').onclick=()=>toast('You’re all caught up. This is a demo workspace.');
let step=0,profile={};try{const saved=JSON.parse(sessionStorage.getItem('funditProfile')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))profile=saved}catch{}window.funditProfile=profile;const steps=['Finances','Household','Work & study','Housing history','Home preferences','Location','Assistance'];
const field=(label,name,type='text',placeholder='Optional')=>`<label>${label}<input name="${name}" type="${type}" placeholder="${placeholder}" ${type==='number'?'min="0"':''}></label>`;
const select=(label,name,options)=>`<label>${label}<select name="${name}"><option value="">Skip / not provided</option>${options.map(o=>`<option>${o}</option>`).join('')}</select></label>`;
const stepInfo=[['Start with the essentials.','Income and monthly obligations help estimate a comfortable payment. Enter gross recurring income; do not include one-time gifts.',()=>field('Your annual gross recurring income','individualIncome','number')+field('Total household annual gross income','householdIncome','number')+field('Monthly take-home income','netIncome','number')+field('Available savings','savings','number')+field('Available down payment','down','number')+field('Closing-cost funds','closing','number')+field('Monthly debt payments','debt','number')+field('Monthly student loan payment','studentPayment','number')+field('Maximum comfortable housing payment','comfortable','number')+select('Credit score range (optional)','credit',['Below 620','620–679','680–739','740+'])],['Who will call this home?','Household size can affect income limits. Household members and mortgage co-applicants are counted separately. Marital status is not needed for this prototype.',()=>field('Adults in household','adults','number')+field('Dependents in household','dependents','number')+field('Mortgage co-applicants','applicants','number')+field('Number of income earners','earners','number')],['Work can open another door.','Employment and institutional benefits may identify research leads. Occupation or student status alone never determines eligibility.',()=>select('Employment status','employment',['Full-time employee','Part-time employee','Self-employed','Independent contractor','Student','Working student','Retired','Unemployed','Other'])+field('Occupation','occupation')+field('Employer','employer')+field('Employment duration (months)','tenure','number')+select('Income source','source',['Employment','Self-employment','Retirement','Other recurring income','Multiple recurring sources'])+select('Enrollment status','student',['Full-time','Part-time','Recently graduated','Not enrolled'])+field('Institution (if relevant)','institution')+select('Employer or institutional housing benefit','benefit',['Yes','No','Unknown'])],['A little housing history.','First-time buyer definitions vary by program. A local reviewer must verify ownership dates and prior assistance.',()=>select('Current living situation','housing',['Renting','Living with family','Living with roommates','Own a home','Temporary housing','Other'])+field('Monthly rent','rent','number')+select('Previously owned a home?','owned',['Yes','No'])+field('Most recent ownership end date','ownershipEnd','date')+select('Previously received buyer assistance?','priorAssistance',['Yes','No','Unsure'])],['What does home look like?','These preferences describe the home you want. They do not determine program eligibility.',()=>select('Property type','property',['Single-family home','Condominium','Townhouse','Duplex','Manufactured home','Other'])+field('Minimum bedrooms','beds','number')+field('Maximum purchase price','price','number')+field('Maximum monthly HOA','hoa','number')+select('Intended use','use',['Primary residence','Owner-occupied multifamily','Co-purchasing','Other'])+field('Home features or accessibility preferences','features')],['Find your place.','Programs often have city-specific boundaries. Your preferred location is chosen by you.',()=>field('Preferred Orange County cities','cities')+field('Preferred ZIP codes','zips')+field('Maximum commute (minutes)','commute','number')+select('Geographic flexibility','flexibility',['Preferred cities only','Open to nearby cities','Anywhere in Orange County'])],['Look for additional support.','These optional answers identify follow-up questions only. Military service and first-generation status never automatically qualify a buyer.',()=>select('Military-related program review (optional)','military',['Request a private eligibility review','No review needed'])+select('First-generation homebuyer review','generation',['Interested in review','No review needed','Unsure'])+field('Known employer or nonprofit program','knownProgram')]];
function saveStep(){new FormData($('#buyerForm')).forEach((v,k)=>profile[k]=v);window.funditProfile=profile;try{sessionStorage.setItem('funditProfile',JSON.stringify(profile))}catch{}}
function renderStep(){if(step>6){$('#steps').innerHTML='';$('#stepContent').innerHTML=`<h2>Your next step is clearer.</h2><p class="muted">${Object.values(profile).filter(Boolean).length} details supplied. Your profile is held only in this session. No eligibility or funds have been confirmed.</p><p>Research leads: local first-time buyer assistance${profile.benefit==='Yes'?', employer benefit review':''}${profile.military==='Request a private eligibility review'?', private military benefit review':''}. Confirm program requirements before counting any award.</p><button type="button" class="secondary" id="useProfile">Use financial details in calculator →</button><button type="button" class="primary" id="findListings">Find listings in this budget →</button><p class="muted">Blank fields remain unknown, not ineligible. You can go back to correct your answers.</p>`;$('#nextStep').textContent='Edit profile';$('#skipStep').style.display='none';$('#useProfile').onclick=()=>{if(profile.householdIncome)$('#income').value=profile.householdIncome;if(profile.down)$('#down').value=profile.down;view('projects');calculate();toast('Available financial details applied; no benefits assumed')};return}$('#steps').innerHTML=steps.map((s,i)=>`<span class="${i===step?'current':''}">${i+1}. ${s}</span>`).join('');let [h,p,f]=stepInfo[step];$('#stepContent').innerHTML=`<h2>${h}</h2><p class="muted">${p}</p><div class="form-grid">${f()}</div>`;$$('#stepContent [name]').forEach(el=>el.value=profile[el.name]||'');$('#prevStep').disabled=step===0;$('#nextStep').textContent=step===6?'Finish profile →':'Continue →';$('#skipStep').style.display='block'}
$('#buyerForm').onsubmit=e=>{e.preventDefault();saveStep();step=step>6?0:step+1;renderStep()};$('#prevStep').onclick=()=>{saveStep();step=Math.max(0,step-1);renderStep()};$('#skipStep').onclick=()=>{saveStep();step++;renderStep()};renderProjects();calculate();renderFunds();renderStep();
